//! The ONE import renderer/parser every store shares — lifted out of `bsc-emit` so the graph-side
//! `bsc graph imports normalize`/`migrate` verbs and the emitter produce byte-identical output BY
//! CONSTRUCTION rather than by agreement (`imports-are-derived-from-the-composes-graph`).
//!
//! The chain is four small, exactly-invertible pieces:
//!
//!   - [`render_import_block`] — a module's `imports` field → TS import lines, one per entry.
//!   - [`parse_import_line`] — its single-line inverse: one rendered line → its [`ImportSpec`].
//!   - [`split_head`] / [`layout`] — separate a module's leading doc-comment from the rest, and the
//!     canonical joiner that re-assembles doc-comment · import block · body with exactly one blank
//!     between non-empty parts.
//!   - [`strip_imports`] (READ, the `migrate` half) and [`body_with_imports`] (WRITE, the emitter
//!     half) are the two directions the migration relies on; because they share [`layout`] and
//!     [`render_import_block`], `body_with_imports(strip_imports(code)) == code` for every
//!     canonically-shaped module — the byte-parity guarantee, proven in `tests` below.
//!
//! It lived in `bsc-emit` while the two directions were proven to agree; it is here now so the
//! graph verbs call the SAME code the build materializer does. `bsc-emit`'s `plan::ImportSpec` is a
//! re-export of this one, so the emitter's call sites are unchanged in meaning.

pub use body_with_imports::body_with_imports;
pub use layout::layout;
pub use parse_import_line::parse_import_line;
pub use render_import_block::render_import_block;
pub use split_head::split_head;
pub use strip_imports::strip_imports;

/// One import to generate for a module — `from` is a record `provides` specifier or an external
/// package; `symbols` are verbatim (aliases kept); `kind` selects the import shape
/// (`named` · `namespace` · `default` · `side-effect`).
#[derive(Clone, Debug, PartialEq)]
pub struct ImportSpec {
    pub from: String,
    pub symbols: Vec<String>,
    pub type_only: bool,
    pub kind: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn spec(from: &str, symbols: &[&str], type_only: bool, kind: &str) -> ImportSpec {
        ImportSpec {
            from: from.into(),
            symbols: symbols.iter().map(|s| s.to_string()).collect(),
            type_only,
            kind: kind.into(),
        }
    }

    #[test]
    fn empty_imports_leaves_code_unchanged() {
        let code = "// doc\nexport const x = 1;\n";
        assert_eq!(body_with_imports(code, &[]), code, "an empty imports field is a no-op");
    }

    #[test]
    fn strip_and_body_with_imports_are_exact_inverses() {
        // For every canonically-shaped module, strip_imports -> body_with_imports is the identity —
        // byte-parity BY CONSTRUCTION, because the two directions share layout()/render_import_block().
        let canonical = [
            "import { foo } from \"@/a\";\n\nexport const x = 1;\n",
            "// doc\n\nimport { foo } from \"@/a\";\n\nexport const x = 1;\n",
            "// a\n// b\n\nimport type { T, U } from \"@/t\";\nimport * as ns from \"@/ns\";\n\nbody();\n",
            "import D from \"@/d\";\nimport \"@/side\";\nimport { foo as bar, baz } from \"@/a\";\n\nrun();\n",
        ];
        for x in canonical {
            let (stripped, specs) = strip_imports(x);
            assert_eq!(body_with_imports(&stripped, &specs), x, "round-trip must be byte-identical for:\n{x}");
        }
    }

    #[test]
    fn parse_import_line_inverts_every_rendered_form() {
        let specs = [
            spec("@/a", &["foo", "bar"], false, "named"),
            spec("@/t", &["T"], true, "named"),
            spec("@/ns", &["ns"], false, "namespace"),
            spec("@/d", &["D"], false, "default"),
            spec("@/s", &[], false, "side-effect"),
            spec("@/a", &["foo as bar", "baz"], false, "named"),
        ];
        for s in specs {
            let line = render_import_block(std::slice::from_ref(&s));
            let parsed = parse_import_line(&line).expect("rendered line must parse");
            assert_eq!(render_import_block(std::slice::from_ref(&parsed)), line);
        }
    }

    #[test]
    fn a_body_line_that_looks_import_ish_is_not_consumed() {
        // strip_imports must not eat a re-export or a quoted body line as if it were an import.
        let code = "export { foo } from \"./bar\";\nconst s = \"hi\";\n";
        let (stripped, specs) = strip_imports(code);
        assert!(specs.is_empty(), "no import lines present");
        assert_eq!(stripped, code, "body left untouched");
    }
}
